<template>
  <main class="promotion-page">
    <PlatformFeeSubnav />
    <header class="promotion-page-head"><div><p class="eyebrow">Giảm phí có kiểm soát</p><h1>Ưu đãi phí nền tảng</h1><p>Ưu đãi chỉ áp dụng cho kỳ mới, có phạm vi, số lượt và ngân sách rõ ràng; không tạo “credit” có thể rút.</p></div><button class="btn primary" type="button" @click="openForm()"><AppIcon name="plus" size="18" /> Tạo ưu đãi nháp</button></header>
    <section class="list-card">
      <div class="filters"><label class="search"><AppIcon name="search" size="17" /><input v-model.trim="filters.q" placeholder="Tìm mã hoặc tên ưu đãi" @keyup.enter="load" /></label><select v-model="filters.status" @change="load"><option value="">Tất cả trạng thái</option><option value="draft">Nháp</option><option value="active">Đã công bố</option><option value="inactive">Ngừng áp dụng</option></select><button class="btn secondary" @click="load">Lọc</button></div>
      <div v-if="loading" class="state">Đang tải ưu đãi...</div><div v-else-if="items.length === 0" class="state"><strong>Chưa có ưu đãi phù hợp</strong></div>
      <div v-else class="table-wrap"><table><thead><tr><th>Ưu đãi</th><th>Mức giảm</th><th>Thời hạn</th><th>Phạm vi</th><th>Ngân sách</th><th>Áp dụng cùng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.code }}</small></td><td><strong>{{ discountLabel(item) }}</strong><small>{{ item.duration_cycles }} kỳ / cụm</small></td><td><strong>{{ date(item.starts_at) }} - {{ date(item.ends_at) }}</strong></td><td><strong>{{ item.applies_to_all_clusters ? 'Tất cả cụm sân' : `${item.assignments?.length || 0} cụm sân` }}</strong></td><td><strong>{{ item.budget_amount ? money(item.budget_amount) : 'Không giới hạn' }}</strong><small>Đã dùng {{ money(item.spent_amount) }}</small></td><td><small>Trả trước: {{ yesNo(item.stackable_with_prepay) }}</small><small>Trả chậm: {{ yesNo(item.applies_to_deferred) }}</small><small>Kỳ lẻ: {{ yesNo(item.applies_to_bridge) }}</small></td><td><span class="status" :class="item.status">{{ statusLabel(item.status) }}</span></td><td><div class="actions"><button v-if="item.status === 'draft'" class="icon-btn" title="Sửa" @click="openForm(item)"><AppIcon name="pencil" size="17" /></button><button v-if="item.status === 'draft'" class="icon-btn green" title="Công bố" @click="requestAction('publish', item)"><AppIcon name="rocket" size="17" /></button><button v-if="item.status === 'active'" class="icon-btn danger" title="Ngừng áp dụng" @click="requestAction('deactivate', item)"><AppIcon name="power" size="17" /></button><button v-if="item.status === 'draft'" class="icon-btn danger" title="Xóa nháp" @click="requestAction('remove', item)"><AppIcon name="trash" size="17" /></button></div></td></tr></tbody></table></div>
    </section>

    <Teleport to="body"><div v-if="formOpen" class="modal-backdrop" @click.self="closeForm"><form class="modal" @submit.prevent="save"><header><div><h2>{{ form.id ? 'Sửa ưu đãi nháp' : 'Tạo ưu đãi nháp' }}</h2><p>Khi đã công bố, cấu hình không thể sửa trực tiếp.</p></div><button class="close-btn" type="button" @click="closeForm"><AppIcon name="x" size="18" /></button></header><div class="modal-body">
      <div class="field-grid"><label>Mã ưu đãi <span>*</span><input v-model.trim="form.code" maxlength="50" required @input="form.code = form.code.toUpperCase()" /><em v-if="errorFor('code')">{{ errorFor('code') }}</em></label><label>Tên ưu đãi <span>*</span><input v-model.trim="form.name" minlength="3" maxlength="150" required /><em v-if="errorFor('name')">{{ errorFor('name') }}</em></label><label>Kiểu giảm <span>*</span><select v-model="form.discount_type"><option value="percent">Theo phần trăm</option><option value="fixed">Số tiền cố định</option></select></label><label>Mức giảm <span>*</span><input v-model.number="form.discount_value" type="number" min="0.01" :max="form.discount_type === 'percent' ? 100 : 999999999999" step="0.01" required /><em v-if="errorFor('discount_value')">{{ errorFor('discount_value') }}</em></label><label v-if="form.discount_type === 'percent'">Giảm tối đa (VND)<input v-model.number="form.max_discount_amount" type="number" min="1" /></label><label>Số kỳ được hưởng / cụm <span>*</span><input v-model.number="form.duration_cycles" type="number" min="1" max="36" required /></label><label>Ngày bắt đầu<input v-model="form.starts_at" type="datetime-local" /></label><label>Ngày kết thúc<input v-model="form.ends_at" type="datetime-local" /></label><label>Ngân sách tổng (VND)<input v-model.number="form.budget_amount" type="number" min="1" /><small>Để trống nếu không giới hạn ngân sách.</small></label><label class="full">Ghi chú nội bộ<textarea v-model.trim="form.notes" rows="2" maxlength="1000"></textarea></label></div>
      <fieldset><legend>Cho phép áp dụng trong trường hợp</legend><div class="checks"><label><input v-model="form.stackable_with_prepay" type="checkbox" /> Cùng giảm trả trước</label><label><input v-model="form.applies_to_deferred" type="checkbox" /> Kỳ thuộc thỏa thuận trả chậm</label><label><input v-model="form.applies_to_bridge" type="checkbox" /> Kỳ lẻ cầu nối</label></div></fieldset>
      <fieldset><legend>Phạm vi cụm sân</legend><label class="scope-all"><input v-model="form.applies_to_all_clusters" type="checkbox" /> Áp dụng cho tất cả cụm sân</label><small v-if="form.applies_to_all_clusters" class="scope-help">Phạm vi được áp dụng động cho toàn hệ thống, kể cả cụm sân được tạo sau này; không lưu danh sách hàng nghìn ID.</small><VenueClusterCombobox v-else v-model="form.venue_cluster_ids" multiple :initial-options="selectedVenueOptions" placeholder="Nhập tên cụm sân hoặc Chủ sân để thêm" /><small v-if="!form.applies_to_all_clusters" class="scope-help"><strong>{{ form.venue_cluster_ids.length }} cụm đã chọn.</strong> Dùng tìm kiếm theo máy chủ cho các trường hợp ngoại lệ; mỗi lần chỉ tải 20 kết quả phù hợp.</small><em v-if="errorFor('venue_cluster_ids')">{{ errorFor('venue_cluster_ids') }}</em></fieldset>
    </div><footer><button class="btn secondary" type="button" @click="closeForm">Hủy</button><button class="btn primary" type="submit" :disabled="busy">Lưu ưu đãi nháp</button></footer></form></div></Teleport>
    <ConfirmModal v-model="confirm.open" :title="confirm.title" :message="confirm.message" :consequence="confirm.consequence" :confirm-text="confirm.confirmText" :type="confirm.type" @confirm="runConfirmed" />
    <p v-if="toast" class="toast" :class="toastType">{{ toast }}</p>
  </main>
</template>

<script>
import AppIcon from '../../components/AppIcon.vue'; import ConfirmModal from '../../components/ConfirmModal.vue'; import PlatformFeeSubnav from '../../components/PlatformFeeSubnav.vue'; import VenueClusterCombobox from '../../components/admin/VenueClusterCombobox.vue'; import { platformFeePromotionService } from '../../services/platformFeePromotion.service.js';
const emptyForm = () => ({ id: null, code: '', name: '', discount_type: 'percent', discount_value: 0, max_discount_amount: null, duration_cycles: 1, applies_to_all_clusters: true, stackable_with_prepay: false, applies_to_deferred: false, applies_to_bridge: false, budget_amount: null, starts_at: '', ends_at: '', venue_cluster_ids: [], cycles_per_cluster: 1, notes: '' }); const emptyConfirm = () => ({ open: false, action: '', item: null, title: '', message: '', consequence: '', confirmText: 'Xác nhận', type: 'warning' });
export default { name: 'AdminPlatformFeePromotions', components: { AppIcon, ConfirmModal, PlatformFeeSubnav, VenueClusterCombobox }, data() { return { items: [], selectedVenueOptions: [], filters: { q: '', status: '' }, loading: true, busy: false, formOpen: false, form: emptyForm(), errors: {}, confirm: emptyConfirm(), toast: '', toastType: 'success' }; }, mounted() { this.load(); }, methods: {
  async load() { this.loading = true; try { this.items = await platformFeePromotionService.list(this.filters); } catch (error) { this.show(error.message || 'Không tải được ưu đãi.', 'error'); } finally { this.loading = false; } },
  openForm(item = null) { this.errors = {}; this.selectedVenueOptions = (item?.assignments || []).map((assignment) => ({ ...(assignment.venue_cluster || {}), id: assignment.venue_cluster_id })); this.form = item ? { ...emptyForm(), ...item, starts_at: this.inputDateTime(item.starts_at), ends_at: this.inputDateTime(item.ends_at), venue_cluster_ids: (item.assignments || []).map((assignment) => String(assignment.venue_cluster_id)), cycles_per_cluster: item.assignments?.[0]?.initial_cycles || item.duration_cycles } : emptyForm(); this.formOpen = true; }, closeForm() { if (!this.busy) this.formOpen = false; },
  async save() { this.busy = true; this.errors = {}; try { const payload = { ...this.form, cycles_per_cluster: this.form.duration_cycles, starts_at: this.form.starts_at || null, ends_at: this.form.ends_at || null, max_discount_amount: this.form.max_discount_amount || null, budget_amount: this.form.budget_amount || null }; const response = this.form.id ? await platformFeePromotionService.update(this.form.id, payload) : await platformFeePromotionService.create(payload); this.formOpen = false; this.show(response.message); await this.load(); } catch (error) { this.errors = error.validation?.errors || error.data?.errors || {}; this.show(error.message || 'Không lưu được ưu đãi.', 'error'); } finally { this.busy = false; } },
  requestAction(action, item) { const config = { publish: ['Công bố ưu đãi?', 'Ưu đãi sẽ tự áp dụng cho các kỳ mới trong thời gian hiệu lực.', 'Kỳ đã phát hành không được tính lại. Ngân sách và số lượt được trừ khi kỳ mới chốt.', 'Công bố', 'warning'], deactivate: ['Ngừng áp dụng ưu đãi?', 'Kỳ mới sẽ không còn được hưởng ưu đãi này.', 'Kỳ đã phát hành giữ nguyên số tiền ưu đãi đã chốt.', 'Ngừng áp dụng', 'danger'], remove: ['Xóa ưu đãi nháp?', 'Ưu đãi nháp chưa công bố sẽ bị xóa.', 'Thao tác không thể hoàn tác.', 'Xóa nháp', 'danger'] }[action]; this.confirm = { open: true, action, item, title: config[0], message: `${item.code} · ${config[1]}`, consequence: config[2], confirmText: config[3], type: config[4] }; },
  async runConfirmed() { const { action, item } = this.confirm; this.confirm = emptyConfirm(); try { const response = action === 'publish' ? await platformFeePromotionService.publish(item.id) : action === 'deactivate' ? await platformFeePromotionService.deactivate(item.id) : await platformFeePromotionService.remove(item.id); this.show(response.message); await this.load(); } catch (error) { this.show(error.message || 'Không thực hiện được thao tác.', 'error'); } },
  errorFor(field) { return this.errors[field]?.[0] || ''; }, inputDateTime(value) { return value ? new Date(value).toISOString().slice(0, 16) : ''; }, date(value) { return value ? new Date(value).toLocaleDateString('vi-VN') : 'Không giới hạn'; }, money(value) { return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value || 0); }, discountLabel(item) { return item.discount_type === 'percent' ? `${Number(item.discount_value)}%${item.max_discount_amount ? `, tối đa ${this.money(item.max_discount_amount)}` : ''}` : this.money(item.discount_value); }, yesNo(value) { return value ? 'Có' : 'Không'; }, statusLabel(status) { return ({ draft: 'Nháp', active: 'Đã công bố', inactive: 'Ngừng áp dụng' })[status] || status; }, show(message, type = 'success') { this.toast = message; this.toastType = type; setTimeout(() => { this.toast = ''; }, 4500); },
} };
</script>

<style scoped>
