rgba(15, 23, 42, .15); background: #ecfdf5; color: #166534; }.toast.error { color: #991b1b; background: #fef2f2; }
@media (max-width: 700px) { .promotion-page-head { align-items: stretch; flex-direction: column; }.filters, .field-grid { grid-template-columns: 1fr; }.full { grid-column: auto; }.promotion-page-head .btn { width: 100%; } }

